#!/usr/bin/env node
// T-STORE check for P1-SETUP-04 (TESTING §7).
// Verifies the native projects generated by `expo prebuild` contain exactly the
// expected Info.plist keys, entitlements, privacy manifest and Android manifest
// permissions. No dependencies; runs in CI, the sandbox and on the Mac.
//
// Usage:
//   node scripts/verify/check-prebuild.mjs [--app apps/mobile] [--variant development|preview|production]
//   node scripts/verify/check-prebuild.mjs --merged <path/to/merged/AndroidManifest.xml>
import { existsSync, readdirSync, readFileSync } from 'node:fs';
import { join, resolve } from 'node:path';

const args = process.argv.slice(2);
const opt = (name, fallback) => {
  const i = args.indexOf(`--${name}`);
  return i >= 0 ? args[i + 1] : fallback;
};

const APP = resolve(opt('app', 'apps/mobile'));
const VARIANT = opt('variant', 'development');
const MERGED = opt('merged', undefined);

const results = [];
const check = (name, ok, detail = '') => results.push({ name, ok, detail });

// ---------- tiny plist parser (dict, array, string, integer, real, true, false, data, date)
function parsePlist(xml) {
  const tokens = xml
    .replace(/<\?xml[^>]*>|<!DOCTYPE[^>]*>/g, '')
    .match(/<[^>]+>|[^<]+/g)
    .map((t) => t.trim())
    .filter(Boolean);
  let i = 0;
  const unescape = (s) =>
    s
      .replace(/&lt;/g, '<')
      .replace(/&gt;/g, '>')
      .replace(/&quot;/g, '"')
      .replace(/&apos;/g, "'")
      .replace(/&amp;/g, '&');
  function value() {
    const t = tokens[i++];
    if (t === '<dict>') {
      const o = {};
      while (tokens[i] !== '</dict>') {
        if (tokens[i] !== '<key>') throw new Error(`plist: expected <key>, got ${tokens[i]}`);
        i++;
        const k = tokens[i] === '</key>' ? '' : unescape(tokens[i++]);
        i++; // </key>
        o[k] = value();
      }
      i++;
      return o;
    }
    if (t === '<dict/>') return {};
    if (t === '<array>') {
      const a = [];
      while (tokens[i] !== '</array>') a.push(value());
      i++;
      return a;
    }
    if (t === '<array/>') return [];
    if (t === '<true/>') return true;
    if (t === '<false/>') return false;
    if (t === '<string/>') return '';
    const m = t.match(/^<(string|integer|real|data|date)>$/);
    if (m) {
      let v = '';
      if (tokens[i] !== `</${m[1]}>`) v = unescape(tokens[i++]);
      i++;
      return m[1] === 'integer' ? parseInt(v, 10) : m[1] === 'real' ? parseFloat(v) : v;
    }
    if (t === '<plist version="1.0">') {
      const v = value();
      return v;
    }
    throw new Error(`plist: unexpected token ${t}`);
  }
  return value();
}

const sameSet = (a, b) =>
  a.length === b.length && [...a].sort().every((x, k) => x === [...b].sort()[k]);
const diff = (actual, expected) => {
  const extra = actual.filter((x) => !expected.includes(x));
  const missing = expected.filter((x) => !actual.includes(x));
  return `${extra.length ? `unexpected: ${extra.join(', ')}` : ''}${extra.length && missing.length ? '; ' : ''}${missing.length ? `missing: ${missing.join(', ')}` : ''}`;
};

// ---------- expectations
const BLOCKED = [
  'android.permission.ACCESS_FINE_LOCATION',
  'android.permission.ACCESS_COARSE_LOCATION',
  'android.permission.ACCESS_BACKGROUND_LOCATION',
  'android.permission.READ_MEDIA_IMAGES',
  'android.permission.READ_MEDIA_VIDEO',
  'android.permission.READ_MEDIA_AUDIO',
  'android.permission.READ_MEDIA_VISUAL_USER_SELECTED',
  'android.permission.READ_EXTERNAL_STORAGE',
  'android.permission.WRITE_EXTERNAL_STORAGE',
  'android.permission.RECORD_AUDIO',
  'android.permission.READ_CONTACTS',
  'android.permission.SCHEDULE_EXACT_ALARM',
  'android.permission.USE_EXACT_ALARM',
  'android.permission.SYSTEM_ALERT_WINDOW',
  'com.google.android.gms.permission.AD_ID',
  // Launcher badge permissions added by ShortcutBadger (via expo-notifications).
  // Android 8+ shows notification dots without them; blocked to keep the
  // Play permission list minimal (DEC 42 CI check).
  'android.permission.READ_APP_BADGE',
  'com.android.launcher.permission.READ_SETTINGS',
  'com.android.launcher.permission.WRITE_SETTINGS',
  'com.android.launcher.permission.INSTALL_SHORTCUT',
  'com.android.launcher.permission.UNINSTALL_SHORTCUT',
  'com.sec.android.provider.badge.permission.READ',
  'com.sec.android.provider.badge.permission.WRITE',
  'com.htc.launcher.permission.READ_SETTINGS',
  'com.htc.launcher.permission.UPDATE_SHORTCUT',
  'com.sonyericsson.home.permission.BROADCAST_BADGE',
  'com.sonymobile.home.permission.PROVIDER_INSERT_BADGE',
  'com.anddoes.launcher.permission.UPDATE_COUNT',
  'com.majeur.launcher.permission.UPDATE_BADGE',
  'com.huawei.android.launcher.permission.CHANGE_BADGE',
  'com.huawei.android.launcher.permission.READ_SETTINGS',
  'com.huawei.android.launcher.permission.WRITE_SETTINGS',
  'com.oppo.launcher.permission.READ_SETTINGS',
  'com.oppo.launcher.permission.WRITE_SETTINGS',
  'me.everything.badger.permission.BADGE_COUNT_READ',
  'me.everything.badger.permission.BADGE_COUNT_WRITE',
];

// Permissions allowed in the final merged manifest (libraries add most of these).
const MERGED_ALLOWED = [
  'android.permission.INTERNET',
  'android.permission.ACCESS_NETWORK_STATE',
  'android.permission.ACCESS_WIFI_STATE',
  'android.permission.CAMERA',
  'android.permission.VIBRATE',
  'android.permission.POST_NOTIFICATIONS',
  'android.permission.RECEIVE_BOOT_COMPLETED',
  'android.permission.WAKE_LOCK',
  'android.permission.USE_BIOMETRIC',
  'android.permission.USE_FINGERPRINT',
  'com.google.android.c2dm.permission.RECEIVE',
  'com.google.android.finsky.permission.BIND_GET_INSTALL_REFERRER_SERVICE',
  'app.onlyswap.DYNAMIC_RECEIVER_NOT_EXPORTED_PERMISSION',
];

const DEV_ONLY_PLIST_KEYS = ['NSLocalNetworkUsageDescription', 'NSBonjourServices'];
const EXPECTED_PLIST_KEYS = [
  'CADisableMinimumFrameDurationOnPhone',
  'CFBundleDevelopmentRegion',
  'CFBundleDisplayName',
  'CFBundleExecutable',
  'CFBundleIdentifier',
  'CFBundleInfoDictionaryVersion',
  'CFBundleName',
  'CFBundlePackageType',
  'CFBundleShortVersionString',
  'CFBundleSignature',
  'CFBundleURLTypes',
  'CFBundleVersion',
  'ITSAppUsesNonExemptEncryption',
  'LSMinimumSystemVersion',
  'LSRequiresIPhoneOS',
  'NSAppTransportSecurity',
  'NSCameraUsageDescription',
  'NSPhotoLibraryUsageDescription',
  'NSUserActivityTypes',
  'RCTMetroPort',
  'UILaunchStoryboardName',
  'UIRequiredDeviceCapabilities',
  'UIRequiresFullScreen',
  'UIStatusBarStyle',
  'UISupportedInterfaceOrientations',
  'UIUserInterfaceStyle',
  'UIViewControllerBasedStatusBarAppearance',
  // R2 (DEC 76, 84): iPad orientations, widgets and Live Activities.
  'UISupportedInterfaceOrientations~ipad',
  'NSSupportsLiveActivities',
  'NSSupportsLiveActivitiesFrequentUpdates',
  'ExpoWidgetsAppGroupIdentifier',
  ...(VARIANT === 'development' ? DEV_ONLY_PLIST_KEYS : []),
];
// Keys that some plugin versions write and others don't (alternate icons).
const OPTIONAL_PLIST_KEYS = ['CFBundleIcons', 'CFBundleIcons~ipad'];
// Usage descriptions allowed in R1.0: camera and photos only (no location, mic, contacts, Face ID).
const ALLOWED_USAGE_KEYS = ['NSCameraUsageDescription', 'NSPhotoLibraryUsageDescription'];

const EXPECTED_ENTITLEMENTS = {
  'aps-environment': 'development',
  'com.apple.developer.associated-domains': ['applinks:onlyswap.pages.dev'],
  'com.apple.developer.declared-age-range': true,
  'com.apple.developer.usernotifications.time-sensitive': true,
  // Widgets read the next meetup from the shared App Group (DEC 84).
  'com.apple.security.application-groups': ['group.app.onlyswap'],
};

// ---------- merged manifest mode (Mac: after gradle processes the release manifest)
function permissionsIn(xml) {
  const perms = [];
  for (const m of xml.matchAll(/<uses-permission(?:-sdk-23)?\b([^>]*)\/?>/g)) {
    const name = m[1].match(/android:name="([^"]+)"/)?.[1];
    const removed = /tools:node="remove"/.test(m[1]);
    if (name) perms.push({ name, removed });
  }
  return perms;
}

if (MERGED) {
  const xml = readFileSync(MERGED, 'utf8');
  const present = [
    ...new Set(
      permissionsIn(xml)
        .filter((p) => !p.removed)
        .map((p) => p.name),
    ),
  ];
  const blockedPresent = present.filter((p) => BLOCKED.includes(p));
  check(
    'merged manifest has none of the blocked permissions',
    blockedPresent.length === 0,
    blockedPresent.join(', '),
  );
  const unknown = present.filter((p) => !MERGED_ALLOWED.includes(p));
  check(
    'merged manifest has only allowed permissions',
    unknown.length === 0,
    unknown.length ? `review: ${unknown.join(', ')}` : present.join(', '),
  );
  const sdk = xml.match(/<uses-sdk[^>]*>/)?.[0] ?? '';
  check('merged manifest minSdk 26', /minSdkVersion="26"/.test(sdk), sdk);
  check('merged manifest targetSdk 36', /targetSdkVersion="36"/.test(sdk), sdk);
  finish();
}

// ---------- iOS
const iosDir = join(APP, 'ios');
if (!existsSync(iosDir)) {
  check('ios/ exists (run `npx expo prebuild --no-install` first)', false);
  finish();
}
const target = readdirSync(iosDir).find((d) => existsSync(join(iosDir, d, 'Info.plist')));
const plist = parsePlist(readFileSync(join(iosDir, target, 'Info.plist'), 'utf8'));
const plistKeys = Object.keys(plist);
const plistCore = plistKeys.filter((k) => !OPTIONAL_PLIST_KEYS.includes(k));
check(
  `Info.plist has exactly the expected keys (${VARIANT})`,
  sameSet(plistCore, EXPECTED_PLIST_KEYS),
  diff(plistCore, EXPECTED_PLIST_KEYS),
);
const usage = plistKeys.filter(
  (k) => /UsageDescription$/.test(k) && !DEV_ONLY_PLIST_KEYS.includes(k),
);
check(
  'usage descriptions: camera and photos only',
  sameSet(usage, ALLOWED_USAGE_KEYS),
  diff(usage, ALLOWED_USAGE_KEYS),
);
check('ITSAppUsesNonExemptEncryption is NO', plist.ITSAppUsesNonExemptEncryption === false);
check(
  'iPhone: portrait only',
  (plist.UISupportedInterfaceOrientations ?? []).every((o) =>
    o.startsWith('UIInterfaceOrientationPortrait'),
  ),
  String(plist.UISupportedInterfaceOrientations),
);
check(
  'iPad: all four orientations (P17-FEAT-02)',
  (plist['UISupportedInterfaceOrientations~ipad'] ?? []).length === 4,
  String(plist['UISupportedInterfaceOrientations~ipad']),
);
check('iPad multitasking (UIRequiresFullScreen false)', plist.UIRequiresFullScreen === false);
const schemes = (plist.CFBundleURLTypes ?? []).flatMap((t) => t.CFBundleURLSchemes ?? []);
check('URL scheme onlyswap registered', schemes.includes('onlyswap'), schemes.join(', '));
check('display name OnlySwap', plist.CFBundleDisplayName === 'OnlySwap');

const ents = parsePlist(readFileSync(join(iosDir, target, `${target}.entitlements`), 'utf8'));
check(
  'entitlements are exactly the expected set',
  JSON.stringify(Object.keys(ents).sort()) ===
    JSON.stringify(Object.keys(EXPECTED_ENTITLEMENTS).sort()),
  diff(Object.keys(ents), Object.keys(EXPECTED_ENTITLEMENTS)),
);
for (const [k, v] of Object.entries(EXPECTED_ENTITLEMENTS)) {
  check(`entitlement ${k}`, JSON.stringify(ents[k]) === JSON.stringify(v), JSON.stringify(ents[k]));
}

const privacy = parsePlist(readFileSync(join(iosDir, target, 'PrivacyInfo.xcprivacy'), 'utf8'));
check(
  'privacy manifest: no tracking',
  privacy.NSPrivacyTracking === false && (privacy.NSPrivacyTrackingDomains ?? []).length === 0,
);
const reasons = Object.fromEntries(
  (privacy.NSPrivacyAccessedAPITypes ?? []).map((t) => [
    t.NSPrivacyAccessedAPIType,
    t.NSPrivacyAccessedAPITypeReasons,
  ]),
);
check(
  'privacy manifest: UserDefaults CA92.1',
  JSON.stringify(reasons.NSPrivacyAccessedAPICategoryUserDefaults) === '["CA92.1"]',
);
check(
  'privacy manifest: FileTimestamp C617.1',
  JSON.stringify(reasons.NSPrivacyAccessedAPICategoryFileTimestamp) === '["C617.1"]',
);

const pbx = readFileSync(join(iosDir, `${target}.xcodeproj`, 'project.pbxproj'), 'utf8');
check('bundle id app.onlyswap', /PRODUCT_BUNDLE_IDENTIFIER = "?app\.onlyswap"?;/.test(pbx));
check(
  'iPhone and iPad (TARGETED_DEVICE_FAMILY = 1,2)',
  /TARGETED_DEVICE_FAMILY = "?1,2"?;/.test(pbx),
);
const podProps = JSON.parse(readFileSync(join(iosDir, 'Podfile.properties.json'), 'utf8'));
check(
  'iOS deployment target 16.4',
  podProps['ios.deploymentTarget'] === '16.4' || /IPHONEOS_DEPLOYMENT_TARGET = 16\.4;/.test(pbx),
  podProps['ios.deploymentTarget'],
);

// ---------- Android
const androidDir = join(APP, 'android');
const manifest = readFileSync(join(androidDir, 'app/src/main/AndroidManifest.xml'), 'utf8');
const perms = permissionsIn(manifest);
const removed = perms.filter((p) => p.removed).map((p) => p.name);
check(
  'every blocked permission is marked tools:node="remove"',
  BLOCKED.every((b) => removed.includes(b)),
  diff(removed, BLOCKED),
);
const kept = perms.filter((p) => !p.removed).map((p) => p.name);
check(
  'app manifest requests only INTERNET and VIBRATE directly',
  sameSet(kept, ['android.permission.INTERNET', 'android.permission.VIBRATE']),
  diff(kept, ['android.permission.INTERNET', 'android.permission.VIBRATE']),
);
check('activity is portrait', /android:screenOrientation="portrait"/.test(manifest));
check('deep link scheme onlyswap', /<data android:scheme="onlyswap"\/>/.test(manifest));
const gradleProps = readFileSync(join(androidDir, 'gradle.properties'), 'utf8');
check('minSdk 26', /^android\.minSdkVersion=26$/m.test(gradleProps));
check('compileSdk 36', /^android\.compileSdkVersion=36$/m.test(gradleProps));
check('targetSdk 36', /^android\.targetSdkVersion=36$/m.test(gradleProps));
check('New Architecture on', /^newArchEnabled=true$/m.test(gradleProps));
const appGradle = readFileSync(join(androidDir, 'app/build.gradle'), 'utf8');
check('applicationId app.onlyswap', /applicationId ['"]app\.onlyswap['"]/.test(appGradle));

finish();

function finish() {
  let failed = 0;
  for (const r of results) {
    if (!r.ok) failed++;
    console.log(`${r.ok ? 'PASS' : 'FAIL'}  ${r.name}${r.detail ? `  (${r.detail})` : ''}`);
  }
  console.log(`\nT-STORE prebuild check: ${results.length - failed}/${results.length} passed`);
  process.exit(failed ? 1 : 0);
}
